#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: tudo o que falta configurar fora do código para a produção funcionar inteira.
#   Vercel (projeto replica): REVALIDATE_SECRET, SITE_URL, SESSION_SECRET, Supabase Auth, Turnstile.
#   GitHub Actions (repo):    REVALIDATE_URL, REVALIDATE_SECRET (etl-pauta.yml, etl.yml após o #13), ANTHROPIC_API_KEY (etl-rascunho.yml).
#   Painel do Supabase:        Site URL, redirects e template do código por e-mail (manual, guiado).
# Já configurado e NÃO tocado aqui: DATA_SOURCE, DATABASE_URL, DATABASE_WRITE_URL, AUTH_PROVIDER, PG_*_POOL_MAX
# (vercel-env-fix.sh) e ETL_DATABASE_URL, ETL_ALERT_WEBHOOK, TRANSPARENCIA_API_KEY, ETL_SCHEDULE_ENABLED (github-actions-setup.sh).
#
# Segredos gerados aqui (REVALIDATE_SECRET, SESSION_SECRET) vão por stdin direto para a Vercel e o GitHub: nunca
# aparecem na tela, em argv ou em arquivo. Chaves coladas também (entrada oculta; testes via curl -K -, não argv).
# Idempotente: o que já existe é pulado, salvo se você pedir para regravar. Nada vai para .env.
#
# Uso: bash etl/deploy/config-producao.sh            # assistente completo
#      bash etl/deploy/config-producao.sh --check    # só o diagnóstico (o que existe e o que falta), sem gravar nada
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
SCOPE="alexandrecamerini"
PROJECT="replica"
SITE="${SITE:-https://replica-virid-sigma.vercel.app}"
export GH_REPO="${GH_REPO:-AlexandreCamerini/replica}"
ENV_FILE="/nonexistent/.env"   # nada é sugerido de .env nem gravado nele
CHECK=0; [[ "${1:-}" == "--check" ]] && CHECK=1

vs() { npx --yes vercel "$@" --scope "$SCOPE"; }
v()  { npx --yes vercel "$@" --scope "$SCOPE" --project "$PROJECT"; }

VLS=""
refresh_vercel() {
  VLS=$(v env ls 2>/dev/null) && grep -qE '^ +name +value +type' <<<"$VLS" ||
    { warn "não consegui listar as variáveis da Vercel (login/rede); nada foi gravado. Rode de novo."; exit 1; }
}
# has_v NAME Production|Preview: a variável existe nesse ambiente da Vercel
has_v() { printf '%s\n' "$VLS" | grep -E "^ +$1 +" | grep -q "$2"; }
GLS=""
refresh_gh() {
  GLS=$(gh secret list 2>/dev/null) || { warn "não consegui listar os secrets do GitHub; rode de novo."; exit 1; }
  GLS=$(printf '%s\n' "$GLS" | awk '{print $1}')
}
has_g() { printf '%s\n' "$GLS" | grep -qx "$1"; }

# vset NAME "production,preview" sensitive|plain VALUE: grava na Vercel por stdin. --force sobrescreve no lugar
# (sem rm antes: se o add falhar, o valor antigo continua lá). Devolve 1 na falha.
vset() {
  local name="$1" envs="$2" kind="$3" value="$4" flag="--sensitive"
  [[ "$kind" == plain ]] && flag="--no-sensitive"
  [[ -n "$value" ]] || { warn "valor vazio para $name; não gravei"; return 1; }
  if printf '%s' "$value" | v env add "$name" --environment "$envs" "$flag" --force --yes >/dev/null 2>&1; then
    printf '  %s✓ Vercel%s %s → %s\n' "$GREEN" "$RESET" "$name" "$envs"
  else
    SKIPPED+=("Vercel $name ($envs): falhou; rode o script de novo"); warn "falhou gravar $name na Vercel"; return 1
  fi
}
# gen: segredo de 64 hex; aborta se o openssl falhar (nunca grava vazio)
gen() { local x; x=$(openssl rand -hex 32) && [[ ${#x} -eq 64 ]] || { warn "openssl falhou"; exit 1; }; printf '%s' "$x"; }
# trim VAR: tira espaço, tab e CR colados junto com a chave
trim() { local x="${!1}"; x="${x//[[:space:]]/}"; printf -v "$1" '%s' "$x"; }

# http_code URL [header...]: status HTTP; cabeçalhos com segredo vão por stdin (curl -K -), nunca em argv
http_code() {
  local url="$1" out; shift
  out=$({ local h; for h in "$@"; do printf 'header = "%s"\n' "$h"; done; } |
    curl -sS -o /dev/null -w '%{http_code}' --max-time 15 -K - "$url" 2>/dev/null || true)
  printf '%s' "${out:-000}"   # curl já escreve 000 quando não conecta
}

status_line() { # status_line LABEL ok? (0/1)
  if [[ "$2" == 1 ]]; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; else printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"; fi
}
b() { "$@" && echo 1 || echo 0; }

diagnose() {
  refresh_vercel; refresh_gh
  say "${BOLD}Vercel · Production${RESET}"
  for n in REVALIDATE_SECRET SITE_URL SESSION_SECRET NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_ANON_KEY SUPABASE_SERVICE_ROLE_KEY NEXT_PUBLIC_TURNSTILE_SITE_KEY TURNSTILE_SECRET_KEY; do
    status_line "$n" "$(b has_v "$n" Production)"
  done
  say "${BOLD}Vercel · Preview${RESET}"
  for n in SESSION_SECRET NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_ANON_KEY NEXT_PUBLIC_TURNSTILE_SITE_KEY TURNSTILE_SECRET_KEY; do
    status_line "$n" "$(b has_v "$n" Preview)"
  done
  say "${BOLD}GitHub Actions · $GH_REPO${RESET}"
  for n in REVALIDATE_URL REVALIDATE_SECRET ANTHROPIC_API_KEY; do status_line "$n" "$(b has_g "$n")"; done
  note "AUTH_PROVIDER=supabase já está nos dois ambientes: sem as chaves do Supabase o login quebra."
  note "Sem TURNSTILE_SECRET_KEY o captcha falha fechado em produção (formulários recusam tudo)."
}

# ── 1 ─────────────────────────────────────────────────────────────────────
if (( CHECK )); then
  command -v gh >/dev/null && gh auth status >/dev/null 2>&1 || { echo "gh sem login (gh auth login)"; exit 1; }
  vs whoami >/dev/null 2>&1 || { echo "Vercel sem login (npx vercel login)"; exit 1; }
  printf '\n%sDiagnóstico · %s%s\n' "$BOLD" "$SITE" "$RESET"; diagnose; exit 0
fi

[[ -t 0 ]] || { echo "Rode num terminal interativo (os prompts leem do teclado)."; exit 1; }
banner "Configuração pendente da produção (Vercel, GitHub, Supabase, Turnstile)"

stage "Pré-requisitos e diagnóstico"
command -v gh >/dev/null || { warn "falta o gh: brew install gh"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh sem login: rode gh auth login e repita"; exit 1; }
command -v npx >/dev/null || { warn "falta o npx (instale Node)"; exit 1; }
vs whoami >/dev/null 2>&1 || { warn "Vercel sem login: rode npx vercel login e repita"; exit 1; }
command -v openssl >/dev/null || { warn "falta o openssl"; exit 1; }
say "Produção: $SITE   ·   Vercel: $SCOPE/$PROJECT   ·   GitHub: $GH_REPO"
diagnose
pause "Enter para seguir (o que já existe é oferecido para pular)"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Revalidação: ETL → POST /api/revalidate"
say "O mesmo segredo precisa estar na Vercel (Production) e no GitHub; a URL só no GitHub."
note "Segredo da Vercel não se lê pela CLI: se faltar de um lado, os dois lados recebem um segredo novo."
REV_SECRET=""
if has_v REVALIDATE_SECRET Production && has_g REVALIDATE_SECRET && ! confirm "Já existe nos dois lados. Gerar um novo (rotacionar)?"; then
  say "Mantido."
else
  REV_SECRET=$(gen)
  if vset REVALIDATE_SECRET production sensitive "$REV_SECRET"; then
    set_secret REVALIDATE_SECRET "$REV_SECRET"; refresh_gh
    has_g REVALIDATE_SECRET || { warn "a Vercel tem o segredo novo e o GitHub não: rode o script de novo (ele rotaciona os dois)"; exit 1; }
    warn "até o redeploy (estágio 8) a produção ainda usa o segredo antigo: um ETL nesse intervalo leva 401 no revalidate"
  else
    REV_SECRET=""; warn "GitHub não foi tocado; os dois lados seguem como estavam"
  fi
fi
if has_g REVALIDATE_URL && ! confirm "REVALIDATE_URL já existe no GitHub. Regravar com $SITE/api/revalidate?"; then
  say "REVALIDATE_URL mantida."
else
  set_secret REVALIDATE_URL "$SITE/api/revalidate"
fi
note "etl-pauta.yml já usa os dois; etl.yml passa a usar quando o PR #13 entrar na main."
pause "Enter para seguir"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "SITE_URL e SESSION_SECRET"
say "SITE_URL faz o og:image sair com URL absoluta (o WhatsApp exige)."
if has_v SITE_URL Production && ! confirm "SITE_URL já existe. Regravar com $SITE?"; then say "Mantida."
else vset SITE_URL production plain "$SITE" || true; fi
say "SESSION_SECRET salga o hash diário de IP do limite de sugestões (sem ela o sal é fixo e público)."
if has_v SESSION_SECRET Production && has_v SESSION_SECRET Preview && ! confirm "SESSION_SECRET já existe. Gerar outra?"; then say "Mantida."
else SS=$(gen); vset SESSION_SECRET production,preview sensitive "$SS" || true; unset SS; fi
pause "Enter para seguir"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase Auth: chaves"
if has_v NEXT_PUBLIC_SUPABASE_URL Production && has_v NEXT_PUBLIC_SUPABASE_ANON_KEY Production && has_v SUPABASE_SERVICE_ROLE_KEY Production \
   && ! confirm "As três chaves já existem. Regravar?"; then
  say "Mantidas."
else
  open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
  step "No projeto de produção: Project Settings → API Keys (e Data API para a URL)."
  step "Project URL: https://<ref>.supabase.co"
  step "Chave pública: 'anon' (legacy, eyJ...) ou 'publishable' (sb_publishable_...)."
  step "Chave de servidor: 'service_role' (eyJ...) ou 'secret' (sb_secret_...). Só vai para Production."
  while :; do
    ask SB_URL "Project URL:"; trim SB_URL; SB_URL="${SB_URL%/}"
    [[ "$SB_URL" =~ ^https://[a-z0-9]{20}\.supabase\.co$ ]] && break
    warn "esperado https://<ref de 20 letras>.supabase.co"
  done
  while :; do
    ask_secret SB_ANON "Chave pública (oculta):"; trim SB_ANON
    # vai para o bundle do navegador: chave de servidor aqui seria vazamento total
    [[ "$SB_ANON" == sb_secret_* ]] && { warn "isso é a chave secreta, não a pública"; continue; }
    if [[ "$SB_ANON" == eyJ* ]]; then
      P=$(printf '%s' "$SB_ANON" | cut -d. -f2 | tr '_-' '/+'); while (( ${#P} % 4 )); do P="$P="; done
      grep -q '"role":"anon"' <<<"$(printf '%s' "$P" | base64 -d 2>/dev/null | tr -d ' ')" || { warn "o JWT não tem role=anon; é a service_role?"; continue; }
    fi
    c=$(http_code "$SB_URL/auth/v1/settings" "apikey: $SB_ANON")
    [[ "$c" == 200 ]] || { warn "a chave pública não abriu $SB_URL/auth/v1/settings (HTTP $c)"; confirm "Tentar de novo?" && continue || exit 1; }
    c=$(http_code "$SB_URL/auth/v1/admin/users?per_page=1" "apikey: $SB_ANON")
    [[ "$c" == 401 || "$c" == 403 ]] || { warn "a chave 'pública' tem acesso de admin (HTTP $c): é a de servidor"; continue; }
    break
  done
  while :; do
    ask_secret SB_SR "Chave de servidor (oculta):"; trim SB_SR
    # chave nova (sb_secret_) vai só no apikey; a legada (JWT) também no Bearer
    if [[ "$SB_SR" == sb_* ]]; then c=$(http_code "$SB_URL/auth/v1/admin/users?per_page=1" "apikey: $SB_SR")
    else c=$(http_code "$SB_URL/auth/v1/admin/users?per_page=1" "apikey: $SB_SR" "Authorization: Bearer $SB_SR"); fi
    [[ "$c" == 200 ]] || { warn "a chave de servidor não listou usuários (HTTP $c); é a anon por engano?"; confirm "Tentar de novo?" && continue || exit 1; }
    break
  done
  say "Chaves conferidas no próprio Supabase."
  vset NEXT_PUBLIC_SUPABASE_URL production,preview plain "$SB_URL" || true
  vset NEXT_PUBLIC_SUPABASE_ANON_KEY production,preview plain "$SB_ANON" || true
  vset SUPABASE_SERVICE_ROLE_KEY production sensitive "$SB_SR" || true
  note "Preview fica sem a chave de servidor: lá, 'apagar conta' falha de propósito."
  unset SB_ANON SB_SR
fi
pause "Enter para seguir"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase Auth: painel (manual)"
open_url "https://supabase.com/dashboard/project/_/auth/url-configuration"
step "Authentication → URL Configuration → Site URL = $SITE"
step "Redirect URLs: adicione $SITE/** e https://replica-git-*-$SCOPE.vercel.app/**"
step "Authentication → Emails → Templates → Magic Link: o corpo precisa ter {{ .Token }}"
step "(o site pede o código de 6 dígitos, não o link)."
note "Opcional (R2): Authentication → Emails → SMTP com o Resend. Sem SMTP próprio o Supabase"
note "manda poucos e-mails por hora, o que trava o login em qualquer pico."
pause "Feito? Enter para seguir"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Turnstile (captcha)"
if has_v NEXT_PUBLIC_TURNSTILE_SITE_KEY Production && has_v TURNSTILE_SECRET_KEY Production && ! confirm "Chaves de produção já existem. Regravar?"; then
  say "Mantidas."
else
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Add widget → nome 'replica' → hostname ${SITE#https://} → modo Managed."
  step "Copie a Site Key e a Secret Key."
  while :; do
    ask TS_SITE "Site Key:"; trim TS_SITE
    [[ "$TS_SITE" =~ ^0x[0-9A-Za-z_-]{20,}$ ]] || { warn "Site Key começa com 0x"; continue; }
    ask_secret TS_SECRET "Secret Key (oculta):"; trim TS_SECRET
    [[ -n "$TS_SECRET" ]] || { warn "vazia"; continue; }
    # token inválido de propósito: com a secret boa, o único erro é o do token
    R=$(printf 'secret=%s&response=teste' "$TS_SECRET" | curl -sS --max-time 15 --data @- https://challenges.cloudflare.com/turnstile/v0/siteverify 2>/dev/null || true)
    grep -q 'invalid-input-response' <<<"$R" && ! grep -q 'invalid-input-secret' <<<"$R" && break
    if [[ -z "$R" ]]; then warn "sem resposta da Cloudflare (rede)"; else warn "a Cloudflare recusou a Secret Key"; fi
    confirm "Tentar de novo?" || exit 1
  done
  say "Secret Key aceita pela Cloudflare."
  vset NEXT_PUBLIC_TURNSTILE_SITE_KEY production plain "$TS_SITE" || true
  vset TURNSTILE_SECRET_KEY production sensitive "$TS_SECRET" || true
  unset TS_SECRET
fi
if ! { has_v TURNSTILE_SECRET_KEY Preview && has_v NEXT_PUBLIC_TURNSTILE_SITE_KEY Preview; }; then
  say "Preview roda como produção: sem chave, os formulários do preview recusam tudo."
  warn "as chaves de teste sempre passam e o Preview usa o banco real: só o login da Vercel protege as sugestões lá"
  if confirm "Gravar no Preview as chaves de teste públicas da Cloudflare?"; then
    vset NEXT_PUBLIC_TURNSTILE_SITE_KEY preview plain "1x00000000000000000000AA" || true
    vset TURNSTILE_SECRET_KEY preview sensitive "1x0000000000000000000000000000000AA" || true
  fi
fi
pause "Enter para seguir"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: ANTHROPIC_API_KEY (rascunhos, opcional)"
say "etl-rascunho.yml gera rascunhos com o Claude; sem a chave ele termina com aviso, sem falhar."
if has_g ANTHROPIC_API_KEY && ! confirm "Já existe. Regravar?"; then say "Mantida."
elif confirm "Configurar agora?"; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Create Key → nome 'replica-etl-rascunho'. Use um workspace com limite de gasto."
  while :; do
    ask_secret AK "Chave (sk-ant-..., oculta):"; trim AK
    [[ "$AK" == sk-ant-* ]] || { warn "esperado sk-ant-..."; continue; }
    c=$(http_code "https://api.anthropic.com/v1/models?limit=1" "x-api-key: $AK" "anthropic-version: 2023-06-01")
    [[ "$c" == 200 ]] && break
    warn "a API recusou a chave (HTTP $c)"; confirm "Tentar de novo?" || break
  done
  if [[ "${c:-}" == 200 ]]; then set_secret ANTHROPIC_API_KEY "$AK"; else SKIPPED+=("ANTHROPIC_API_KEY no GitHub (chave recusada)"); fi
  unset AK
else
  SKIPPED+=("ANTHROPIC_API_KEY no GitHub (rascunhos desligados)")
fi
pause "Enter para seguir"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Redeploy e verificação"
say "Variáveis da Vercel (e as NEXT_PUBLIC_*, que entram no build) só valem depois de um redeploy."
note "Oferecido sempre: se uma execução anterior parou no meio, o redeploy dela pode não ter acontecido."
if :; then
  PROD_DPL=$(vs inspect "$SITE" 2>&1 | awk '$1=="url" && !f {print $2; f=1}' || true)  # awk lê tudo: sem SIGPIPE no node
  if [[ -n "$PROD_DPL" ]] && confirm "Refazer o deploy de produção ($PROD_DPL) agora?"; then
    vs redeploy "$PROD_DPL" >/dev/null 2>&1 && say "Redeploy pronto." || warn "redeploy falhou; refaça pelo painel da Vercel"
  else
    SKIPPED+=("redeploy de produção (Vercel → Deployments → Redeploy)")
  fi
  note "Previews pegam as variáveis no próximo push de cada branch."
fi
c=$(http_code "$SITE/")
status_line "home responde ($c)" "$([[ $c == 200 ]] && echo 1 || echo 0)"
if [[ -n "$REV_SECRET" ]]; then
  R=$(printf 'header = "Authorization: Bearer %s"\nheader = "Content-Type: application/json"\n' "$REV_SECRET" |
      curl -sS --max-time 20 -K - -d '{"tags":["data"]}' "$SITE/api/revalidate" 2>/dev/null || true)
  status_line "revalidate com o segredo novo: $R" "$(grep -q revalidated <<<"$R" && echo 1 || echo 0)"
  grep -q revalidated <<<"$R" || note "se respondeu 'não autorizado', o deploy ainda não pegou o segredo: refaça o redeploy."
  unset REV_SECRET
fi
refresh_gh; refresh_vercel
pause "Enter para o resumo"
finish
diagnose
